// DEV_RIO_705 Threads×楽天【下書き準備のみ・dry-run】。
// Threads投稿に添える『楽天アフィリのリプライ下書き案』を生成。★自動リプライ・自動投稿はしない。
// 実アフィリリンクは作らない。人間が自分の楽天アフィリID付きリンクを差し込み、手動で投稿する。
const i = $input.first().json;
return [{ json: {
  content_id: i.content_id ?? 'ca-threads-aff-001',
  threads_post: i.threads_post ?? '（Threads投稿本文）',
  platform: 'threads',
  action_type: 'prepare_rakuten_reply_draft'
} }];

