parameters.jsCode:
// Claude応答をパース。リプライ案にリンク差し込み欄を付与して停止。
const prev = $input.first().json;
let replies = [];
try {
  const text = prev?.content?.[0]?.text ?? '[]';
  const match = text.match(/\[[\s\S]*\]/);
  replies = match ? JSON.parse(match[0]) : [];
} catch (e) {
  replies = [{ reply: '手動で作成してください', product_genre: 'parse_error', error: String(e) }];
}
const ctx = $('Ingest Post').first().json;
const enriched = replies.map((r, idx) => ({
  ...r,
  rakuten_link_placeholder: `<<ここに自分の楽天アフィリID付きリンクを貼る #${idx + 1}>>`
}));
return [{ json: {
  content_id: ctx.content_id,
  reply_drafts: enriched,
  draft_count: enriched.length,
  state: 'WAITING_APPROVAL',
  published: false,
  note: 'dry-run。Threads楽天リプライの下書き案のみ。★自動リプライ・自動投稿はしない。人間が自分の楽天アフィリリンクを差し込み、手動で投稿する（CLAUDE.md 準拠）。'
} }];
